import pathlib,json,numpy as np,pandas as pd
from scipy.stats import rankdata,spearmanr
b=pathlib.Path.cwd()/'research/codex';p=pd.read_parquet(b/'R021_inputs/mesh500.parquet',columns=['MESH_ID','SHICODE','PTN_2020']);f=pd.read_parquet(b/'R240_v2_15min_replay/national_coverage_flags.parquet',columns=['MESH_ID','current_15']);p['MESH_ID']=p.MESH_ID.astype(str);f['MESH_ID']=f.MESH_ID.astype(str);m=p.merge(f,on='MESH_ID',validate='many_to_one',how='left');assert not m.current_15.isna().any();m['municipality']=m.SHICODE.astype(str).str.extract(r'^(\d{5})');assert not m.municipality.isna().any();m['covered']=m.PTN_2020*m.current_15
agg=m.groupby('municipality').agg(population=('PTN_2020','sum'),covered=('covered','sum'),meshes=('MESH_ID','nunique')); s=pd.read_csv(b/'R018_station_nearest_municipality_repro.csv',dtype={'municipality':str});counts=s.groupby('municipality').size();agg['sites']=counts.reindex(agg.index,fill_value=0);assert len(agg)==1884 and len(s)==16337 and agg.sites.sum()==16337;agg['density']=agg.population/(agg.meshes*.25);agg['coverage']=agg.covered/agg.population;agg['sites_per100k']=agg.sites/agg.population*100000
assert np.isfinite(agg[['density','coverage','sites_per100k']]).all().all();y=rankdata(agg.coverage);x=rankdata(agg.density);z=rankdata(agg.sites_per100k);corr=np.corrcoef([y,x,z]);partial_yx_z=(corr[0,1]-corr[0,2]*corr[1,2])/np.sqrt((1-corr[0,2]**2)*(1-corr[1,2]**2));partial_yz_x=(corr[0,2]-corr[0,1]*corr[1,2])/np.sqrt((1-corr[0,1]**2)*(1-corr[1,2]**2));r={'municipal_units':len(agg),'station_records':len(s),'spearman_density_coverage':float(corr[0,1]),'spearman_station_rate_coverage':float(corr[0,2]),'spearman_density_station_rate':float(corr[1,2]),'partial_rank_density_control_station_rate':float(partial_yx_z),'partial_rank_station_rate_control_density':float(partial_yz_x),'method':'Pearson correlation of average ranks, partialled analytically; unweighted municipality units; SHICODE first five digits; nearest population mesh station assignment'};out=b/'R018_partial_rank_repro.json';out.write_text(json.dumps(r,ensure_ascii=False,indent=2),encoding='utf-8');print(json.dumps(r,ensure_ascii=False))
